presets.prompt:
{subject}, {
  "type": "cinematic_character_design_sheet",
  "intent": "film_production_pitch_board",
  "core_directive": {
    "layout_rules": [
      "no generic layouts",
      "no evenly spaced grids",
      "no forced symmetry",
      "intentional asymmetry",
      "art-directed composition"
    ]
  },
  "character_identity": {
    "name": "[Full character name]",
    "alias": "[Nickname / codename]",
    "age": "[Real or stylized age]",
    "height": "[Exact height cm/ft]",
    "build": "[Detailed body proportions, weight distribution, posture]"
  },
  "ethnicity_design_language": "[Hybrid style: Pixar / anime / cultural realism]",
  "face_design": {
    "structure": "[Face shape, bone structure, asymmetry]",
    "skin": "[Texture, tone, imperfections]",
    "eyes": "[Size, spacing, color, quirks]",
    "hair": "[Style, physics, imperfections]",
    "distinct_features": "[Scars, dimples, unique traits]"
  },
  "psychological_profile": {
    "core_traits": [
      "trait1",
      "trait2",
      "trait3"
    ],
    "internal_conflict": "[Desire vs sabotage]",
    "behavior_patterns": [
      "[Habit 1]",
      "[Habit 2]",
      "[Habit 3]"
    ],
    "emotional_baseline": "[Default state + shift speed]"
  },
  "performance_direction": {
    "expression_notes": [
      "micro-expressions",
      "no staged symmetry",
      "transitional emotion"
    ],
    "body_language": {
      "posture": "[Tendencies]",
      "movement": "[Rhythm]",
      "idle_behavior": "[Fidget/stillness]"
    }
  },
  "wardrobe": {
    "primary_outfit": [
      "[Garment 1: fabric + wear]",
      "[Garment 2: fit + stitching]",
      "[Layering logic]"
    ],
    "footwear": "[Material + wear]",
    "accessories": "[Functional + character items]",
    "props": "[Recurring objects]"
  },
  "materials_textures": {
    "fabric": "visible stretch, wrinkles, stitching",
    "surface": "no plastic look unless intentional",
    "skin": "soft light bounce",
    "imperfections": "dirt, aging, smudges"
  },
  "turnaround": [
    "front_view",
    "3_4_view",
    "side_view",
    "back_view",
    "3_4_back_view"
  ],
  "head_study": {
    "views": [
      "front_neutral",
      "3_4_primary_expression",
      "profile",
      "looking_down_[emotion]",
      "looking_up_[emotion]",
      "dynamic_angle_[intense_emotion]"
    ]
  },
  "cinematic_portrait": {
    "environment": "[Story-driven location]",
    "lighting": "[Practical + ambient]",
    "color_tone": "[Warm/cool palette]",
    "expression": "[Narrative moment]",
    "camera": "[Lens + shallow DOF]"
  },
  "camera_lighting": {
    "full_body": {
      "lens": "35mm",
      "lighting": "soft key + bounce",
      "exposure": "natural"
    },
    "portrait": {
      "lens": "85mm",
      "depth_of_field": "shallow",
      "focus": "eyes"
    }
  },
  "composition_layout": {
    "background": "neutral gray",
    "elements": [
      "height scale",
      "annotation callouts",
      "wardrobe breakdown",
      "production notes"
    ],
    "style": "premium studio board"
  },
  "style": {
    "type": "[e.g. Pixar-style realism]",
    "features": [
      "appealing exaggeration",
      "soft geometry",
      "cinematic lighting",
      "high emotional readability"
    ]
  },
  "consistency_rule": "no variation across views",
  "output_quality": [
    "high detail",
    "sharp focus",
    "production-ready",
    "pitch-deck quality"
  ]
}

{subject}, {
  "prompt": "超写实，一位留着深色短卷发、修剪整齐的胡须和黑色方形眼镜的年轻男子的鲜艳逼真渲染，身穿深色纹理高领毛衣和牛仔裤。他奔跑到一半被捕捉下来，姿态充满动感，向前突破，充满戏剧性地从一个破碎的漫画分镜框中显现——一条腿和一只手臂冲入现实世界，而身体的其余部分仍留在漫画框内。他的表情充满活力和喜悦，拥有锐利的面部细节，自然的皮肤纹理，以及具有高对比度和深度的戏剧性电影灯光。\n\n背景：一个非常详细的黑白漫画布局，充满了幽默、夸张的且与他直接互动的反应场景。周围的漫画人物表现出震惊和喜剧的表情，配有粗体的对话气泡和速度线。漫画分镜采用经典的高对比度水墨风格绘制，线条清晰，网点阴影。撕裂的纸张边缘和碎片增强了他冲破漫画世界的幻觉。全彩色的写实人物与单色的漫画环境形成强烈对比，创造出写实与漫画艺术之间的动态混合体。超精细，8k分辨率，清晰聚焦，戏剧性的阴影，电影级景深。"
}

{subject}, {
  "type": "6格漫画页面",
  "aspect_ratio": "2:3竖版人像",
  "art_style": "精细的动漫漫画，高对比度，电影级光照",
  "panel_borders": "粗白色分格线清晰分隔每个画格，每个画格之间有可见的白色留白，每个单独画格周围有硬质黑色边框轮廓，传统漫画页面网格布局",
  "color_palette": {
    "primary": "深海军蓝（非纯黑）暗室背景",
    "secondary": "温暖的琥珀色/橙色台灯光晕",
    "accent": "冷蓝色笔记本电脑屏幕光",
    "effects": "明亮的红色恐慌特效，白色对话气泡",
    "panel_gutters": "画格之间干净明亮的白色分隔线"
  },
  "characters": {
    "character_A": "扎着双马尾戴眼镜的女孩，深色校服，红色蝴蝶结",
    "character_B": "棕色短发女孩，深色校服，起初趴在桌上睡觉"
  },
  "setting": "凌晨2:47的黑暗卧室书桌，单一温暖的台灯，打开的笔记本电脑，散落的笔记和课本，海军蓝背景",
  "layout": {
    "sections": [
      {
        "panel": 1,
        "position": "顶部，宽幅",
        "description": "深海军蓝房间。上方有温暖的灯光，下方有冷蓝色的笔记本电脑光晕。角色A弓着背在书桌前学习。角色B趴在她旁边睡觉。电子钟清晰显示凌晨2:47。戏剧性的阴影对比。可见白色画格边框。"
      },
      {
        "panel": 2,
        "position": "中上偏左",
        "description": "角色A面部的特写，被下方蓝色的笔记本电脑光晕照亮，因恐惧而睁大双眼。红色闪电恐慌特效。对话气泡写着‘等等……我保存了吗？！’画框周围清晰可见白色画格边框。"
      },
      {
        "panel": 3,
        "position": "中上偏右",
        "description": "角色A的特写，空洞布满血丝的眼睛，死鱼眼凝视，被冷蓝色光晕照亮。对话气泡写着‘我不记得睡眠是什么了……’清晰可见白色画格边框。"
      },
      {
        "panel": 4,
        "position": "中下，宽幅",
        "description": "角色A双手猛拍桌子尖叫‘全都没了！！’左侧有巨大的白色猛拍音效字。角色B猛然惊醒。书本四处飞散。海军蓝背景。四周有粗白色画格边框。"
      },
      {
        "panel": 5,
        "position": "底部偏上，宽幅",
        "description": "角色A举着显示自动保存通知的笔记本电脑，精神错乱的狂热笑容，身后散发红色和金色闪光特效。对话气泡写着‘自动保存……技术就是神’。清晰的白色画格边框。"
      },
      {
        "panel": 6,
        "position": "底部偏下，宽幅",
        "description": "前景中的角色B面无表情生无可恋，眼下有浓重的黑眼圈。背景显示角色A正在亲吻笔记本电脑，带有啾啾啾闪光特效。角色B有一个小的‘……’对话气泡。清晰可见白色画格边框。"
      }
    ]
  },
  "global_notes": "关键：所有6个画格必须由中等大小的明亮白色留白线清晰分隔。画格之间不应相互溢出。画格之间的页面背景为白色。应使用深海军蓝代替纯黑色以保持深度可见。"
}
